/* ─────────────────────────────────────────────
   SCROLL REVEAL HOOK
───────────────────────────────────────────── */
function useReveal() {
  useEffect(() => {
    const els = document.querySelectorAll(".section-in");
    const obs = new IntersectionObserver(
      entries => entries.forEach(e => { if(e.isIntersecting) e.target.classList.add("visible"); }),
      { threshold: 0.12 }
    );
    els.forEach(el => obs.observe(el));
    return () => obs.disconnect();
  }, []);
}

/* ─────────────────────────────────────────────
   NOW/NEXT/THEN MOCK CARD
───────────────────────────────────────────── */
function NowNextThenCard() {
  const [tick, setTick] = useState(0);
  useEffect(() => { const id = setInterval(() => setTick(t => t + 1), 1000); return () => clearInterval(id); }, []);
  const totalSecs = 900;
  const rem = Math.max(0, totalSecs - (tick % totalSecs));
  const mins = String(Math.floor(rem / 60)).padStart(2, "0");
  const secs = String(rem % 60).padStart(2, "0");
  const prog = rem / totalSecs;
  const r = 36; const circ = 2 * Math.PI * r;

  return (
    <div style={{
      background:"rgba(255,255,255,0.92)", backdropFilter:"blur(20px)",
      borderRadius:24, padding:"20px 18px", border:`1px solid ${T.border}`,
      boxShadow:"0 20px 60px rgba(0,0,0,0.10)", width:320, fontFamily:FONT_BODY,
    }}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
        <span style={{fontSize:11,fontWeight:700,letterSpacing:".1em",textTransform:"uppercase",color:T.teal}}>Today's Flow</span>
        <span style={{fontSize:10,fontWeight:600,color:T.sage,background:T.sageL,padding:"2px 8px",borderRadius:20}}>LIVE</span>
      </div>

      <div style={{
        background:`linear-gradient(135deg,${T.tealL},rgba(255,255,255,0.6))`,
        borderRadius:16, padding:"14px", marginBottom:8,
        border:`1.5px solid ${T.teal}33`,
      }}>
        <div style={{fontSize:9,fontWeight:800,letterSpacing:".12em",textTransform:"uppercase",color:T.teal,marginBottom:6}}>NOW</div>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <span style={{fontSize:28}}>📚</span>
            <div>
              <div style={{fontSize:15,fontWeight:700,color:T.ink}}>Reading</div>
              <div style={{fontSize:10,color:T.inkSoft,marginTop:1}}>15 min block</div>
            </div>
          </div>
          <svg width={92} height={92} style={{flexShrink:0}}>
            <circle cx={46} cy={46} r={r} fill="none" stroke="rgba(0,0,0,0.07)" strokeWidth={7}/>
            <circle cx={46} cy={46} r={r} fill="none" stroke={T.teal} strokeWidth={7}
              strokeLinecap="round" strokeDasharray={circ} strokeDashoffset={circ*(1-prog)}
              transform="rotate(-90 46 46)" style={{transition:"stroke-dashoffset 1s linear"}}/>
            <text x={46} y={44} textAnchor="middle" style={{fontSize:12,fontWeight:700,fill:T.ink,fontFamily:FONT_BODY}}>{mins}</text>
            <text x={46} y={57} textAnchor="middle" style={{fontSize:10,fill:T.inkSoft,fontFamily:FONT_BODY}}>{secs}</text>
          </svg>
        </div>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        {[{label:"NEXT",emoji:"✏️",title:"Writing",color:T.sky,light:T.skyL},
          {label:"THEN",emoji:"🔢",title:"Math",color:T.gold,light:T.goldL}].map(c=>(
          <div key={c.label} style={{background:c.light,borderRadius:12,padding:"10px",border:`1px solid ${c.color}33`}}>
            <div style={{fontSize:8,fontWeight:800,letterSpacing:".1em",textTransform:"uppercase",color:c.color,marginBottom:4}}>{c.label}</div>
            <div style={{display:"flex",alignItems:"center",gap:6}}>
              <span style={{fontSize:18}}>{c.emoji}</span>
              <span style={{fontSize:12,fontWeight:700,color:T.ink}}>{c.title}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

