function Pilot() {
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [school, setSchool] = useState("");
  const [role, setRole] = useState("");
  const [sent, setSent] = useState(false);

  function handleSubmit(e) {
    e.preventDefault();
    if(email) setSent(true);
  }

  return (
    <section id="pilot" style={{
      padding:"120px 24px",
      background:`linear-gradient(180deg,${T.cream} 0%,white 100%)`,
      position:"relative",overflow:"hidden",
    }}>
      <div style={{position:"absolute",top:"10%",left:"50%",transform:"translateX(-50%)",
        width:800,height:600,borderRadius:"50%",
        background:`radial-gradient(circle,${T.tealL} 0%,transparent 65%)`,
        pointerEvents:"none",opacity:.6}}/>
      <div style={{maxWidth:640,margin:"0 auto",position:"relative",textAlign:"center"}}>
        <div className="section-in">
          <div className="chip" style={{background:T.tealL,color:T.tealD,border:`1px solid ${T.teal}44`,marginBottom:24,display:"inline-flex"}}>
            ◉ Early Access
          </div>
          <h2 style={{fontFamily:FONT_DISPLAY,fontSize:"clamp(36px,5vw,62px)",fontWeight:400,lineHeight:1.08,letterSpacing:"-.02em",color:T.ink,marginBottom:18}}>
            Join the<br/><em style={{fontStyle:"italic",color:T.teal}}>pilot program.</em>
          </h2>
          <p style={{fontSize:17,color:T.inkMid,lineHeight:1.7,marginBottom:40}}>
            ClassPulse is currently preparing for early classroom pilots.
            We're partnering with K–12 teachers and administrators who want
            to bring calmer, more predictable classroom flow to their school —
            at no cost during the pilot period.
          </p>

          {sent ? (
            <div style={{background:T.tealL,borderRadius:20,padding:"32px 28px",border:`1.5px solid ${T.teal}44`}}>
              <div style={{fontSize:32,marginBottom:12}}>🌿</div>
              <div style={{fontFamily:FONT_DISPLAY,fontSize:24,color:T.tealD,marginBottom:8}}>You're on the list.</div>
              <p style={{fontSize:14,color:T.inkMid,lineHeight:1.65}}>
                We'll be in touch shortly with next steps.
                Thank you for bringing ClassPulse into your classroom.
              </p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} style={{display:"flex",flexDirection:"column",gap:12,textAlign:"left"}}>
              {[
                {val:name,set:setName,placeholder:"Your name",type:"text"},
                {val:email,set:setEmail,placeholder:"Your email address",type:"email"},
                {val:school,set:setSchool,placeholder:"School or district name",type:"text"},
              ].map((f,i)=>(
                <input key={i} type={f.type} value={f.val} onChange={e=>f.set(e.target.value)}
                  placeholder={f.placeholder} required={f.type==="email"}
                  style={{
                    padding:"14px 18px",borderRadius:12,
                    border:`1.5px solid ${T.border}`,background:"white",
                    fontSize:14,fontFamily:FONT_BODY,color:T.ink,outline:"none",transition:"border-color .15s",
                  }}
                  onFocus={e=>e.target.style.borderColor=T.teal}
                  onBlur={e=>e.target.style.borderColor=T.border}/>
              ))}
              <select value={role} onChange={e=>setRole(e.target.value)} style={{
                padding:"14px 18px",borderRadius:12,border:`1.5px solid ${T.border}`,
                background:"white",fontSize:14,fontFamily:FONT_BODY,
                color:role?T.ink:T.inkSoft,outline:"none",appearance:"none",
              }}>
                <option value="">Role (optional)</option>
                {["Classroom Teacher","Special Education Teacher","Instructional Aide","School Administrator","Curriculum Coordinator","Other"].map(r=>(
                  <option key={r} value={r}>{r}</option>
                ))}
              </select>
              <button type="submit" className="btn-primary" style={{justifyContent:"center",padding:"15px 24px",fontSize:15,marginTop:4}}>
                Request Pilot Access →
              </button>
              <p style={{fontSize:11,color:T.inkSoft,textAlign:"center",lineHeight:1.5}}>
                Free during the pilot period. No student data collected. Setup in under 5 minutes.
              </p>
            </form>
          )}
        </div>
      </div>
    </section>
  );
}

